-- Farmer Activity Audit core schema. Applied to Supabase project xipngakadtsalyohgugb on 2026-10-29.
-- All tenant-owned records carry org_id. Do not store raw phone numbers in analytics or logs.
create extension if not exists pgcrypto;
create table if not exists public.faa_organizations(id uuid primary key default gen_random_uuid(),name text not null,status text not null default 'active' check(status in('active','suspended','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.faa_organization_members(org_id uuid not null references public.faa_organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'viewer' check(role in('owner','admin','auditor','reviewer','viewer')),created_at timestamptz not null default now(),primary key(org_id,user_id));
create or replace function public.faa_is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.faa_organization_members m where m.org_id=target_org and m.user_id=auth.uid()) $$;
create or replace function public.faa_has_org_role(target_org uuid,allowed_roles text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.faa_organization_members m where m.org_id=target_org and m.user_id=auth.uid() and m.role=any(allowed_roles)) $$;
create table if not exists public.faa_products(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,sku text not null,name text not null,category text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,sku));
create table if not exists public.faa_product_knowledge_versions(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,product_id uuid not null references public.faa_products(id) on delete cascade,version integer not null check(version>0),language text not null default 'hi' check(language in('hi','bho','en')),content_json jsonb not null default '{}'::jsonb,source_refs jsonb not null default '[]'::jsonb,status text not null default 'draft' check(status in('draft','in_review','approved','rejected','retired')),approved_by uuid references auth.users(id) on delete set null,approved_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(product_id,version),check(status<>'approved' or(approved_by is not null and approved_at is not null)));
create table if not exists public.faa_activities(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,external_ref text,staff_ref text not null,village text not null,district text,state text,activity_date date not null,activity_type text not null default 'farmer_meeting',source_file text,import_batch_id uuid,status text not null default 'imported' check(status in('imported','validated','sampling','in_audit','completed','needs_review','cancelled')),metadata jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.faa_farmers(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,external_ref text,full_name text,phone_encrypted text,phone_hmac text,preferred_language text not null default 'hi' check(preferred_language in('hi','bho','en','other')),village text,district text,state text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,phone_hmac));
create table if not exists public.faa_activity_participants(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,activity_id uuid not null references public.faa_activities(id) on delete cascade,farmer_id uuid not null references public.faa_farmers(id) on delete cascade,product_id uuid references public.faa_products(id) on delete set null,participation_status text not null default 'reported' check(participation_status in('reported','confirmed','denied','uncertain','not_reached')),consent_status text not null default 'unknown' check(consent_status in('unknown','eligible','declined','withdrawn','suppressed')),consent_source text,consent_purpose text,consent_at timestamptz,recording_consent_status text not null default 'unknown' check(recording_consent_status in('unknown','granted','declined','not_applicable')),last_contact_at timestamptz,retry_count integer not null default 0 check(retry_count>=0),created_at timestamptz not null default now(),unique(activity_id,farmer_id,product_id));
create table if not exists public.faa_sampling_batches(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,activity_id uuid not null references public.faa_activities(id) on delete cascade,sample_size integer not null check(sample_size>0),method text not null default 'simple_random' check(method in('simple_random','stratified')),seed text not null,status text not null default 'draft' check(status in('draft','approved','queued','running','completed','cancelled')),approved_by uuid references auth.users(id) on delete set null,approved_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(status not in('approved','queued','running','completed') or(approved_by is not null and approved_at is not null)));
create table if not exists public.faa_audit_calls(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,sampling_batch_id uuid not null references public.faa_sampling_batches(id) on delete cascade,participant_id uuid not null references public.faa_activity_participants(id) on delete cascade,knowledge_version_id uuid references public.faa_product_knowledge_versions(id) on delete set null,provider text,provider_call_id text,status text not null default 'queued' check(status in('queued','scheduled','initiated','ringing','answered','completed','no_answer','failed','cancelled','opted_out')),attempt_number integer not null default 1 check(attempt_number>0),started_at timestamptz,ended_at timestamptz,duration_seconds integer check(duration_seconds is null or duration_seconds>=0),recording_object_path text,transcript_object_path text,language_used text check(language_used is null or language_used in('hi','bho','en','other')),created_at timestamptz not null default now(),unique(provider,provider_call_id));
create table if not exists public.faa_call_assessments(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.faa_organizations(id) on delete cascade,call_id uuid not null unique references public.faa_audit_calls(id) on delete cascade,answers_json jsonb not null default '[]'::jsonb,communication_score numeric(5,2) check(communication_score is null or communication_score between 0 and 100),understanding_score numeric(5,2) check(understanding_score is null or understanding_score between 0 and 100),confidence numeric(5,4) check(confidence is null or confidence between 0 and 1),review_status text not null default 'pending' check(review_status in('pending','not_required','required','in_review','approved','overturned')),review_reason text,reviewer_id uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.faa_audit_events(id bigint generated always as identity primary key,org_id uuid not null references public.faa_organizations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists faa_activities_org_date_idx on public.faa_activities(org_id,activity_date desc);
create index if not exists faa_activities_staff_date_idx on public.faa_activities(org_id,staff_ref,activity_date desc);
create index if not exists faa_participants_consent_idx on public.faa_activity_participants(org_id,consent_status);
create index if not exists faa_calls_status_idx on public.faa_audit_calls(org_id,status,created_at desc);
create index if not exists faa_assessments_review_idx on public.faa_call_assessments(org_id,review_status);
create or replace function public.faa_set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['faa_organizations','faa_products','faa_activities','faa_farmers','faa_call_assessments'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I',t||'_updated_at',t); EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.faa_set_updated_at()',t||'_updated_at',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['faa_organizations','faa_organization_members','faa_products','faa_product_knowledge_versions','faa_activities','faa_farmers','faa_activity_participants','faa_sampling_batches','faa_audit_calls','faa_call_assessments','faa_audit_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
-- Organization policies and helper grants are applied in the follow-up security migration.
